1	// Plain (non-"use server") module: shared types for the in-portal file manager.
2	// A "use server" file may ONLY export async functions — exporting the FileEntry
3	// type from lib/actions-files.ts triggered Next's
4	// "A 'use server' file can only export async functions, found object" error when
5	// the Files tab invoked a server action, so the type lives here and is imported
6	// (as a type) by both the server actions and the FileManager client component.
7	
8	export type FileEntry = {
9	  name: string;
10	  isDirectory: boolean;
11	  size: number;
12	  modifiedMs: number;
13	  /** Octal permission string like "755", or null if unknown. */
14	  mode: string | null;
15	};
16

1	"use server";
2	
3	/**
4	 * Owned-server-scoped server actions for the in-portal file manager.
5	 *
6	 * Every action:
7	 *   - authenticates the caller and verifies they OWN the target server
8	 *     (admins may act on any server), mirroring the `ownedServer` pattern in
9	 *     lib/actions-server-lifecycle.ts;
10	 *   - normalizes + validates the path (rejects `..` traversal, requires an
11	 *     absolute path, clamps length) via lib/sftp helpers;
12	 *   - enforces size limits on text edits;
13	 *   - rate-limits per user;
14	 *   - returns a typed { ok, error?, ... } result — never throws raw internals
15	 *     at the client, and never exposes another user's server.
16	 *
17	 * The heavy lifting (real SFTP vs. sandbox simulation) lives in lib/sftp.ts.
18	 */
19	import { db } from "./db";
20	import { requireUser } from "./auth";
21	import { checkRateLimit } from "./rate-limit";
22	import type { FileEntry } from "./files-types";
23	import {
24	  listDir,
25	  statPath,
26	  readFileText,
27	  writeFileText,
28	  mkdirPath,
29	  renamePath,
30	  removePath,
31	  chmodPath,
32	  writeFileBuffer,
33	  normalizePath,
34	  validateName,
35	  joinPath,
36	  sanitizeUploadName,
37	  UPLOAD_DIR,
38	  type SftpEntry,
39	} from "./sftp";
40	
41	/** Max size (bytes) for a text file opened/saved in the inline editor. */
42	const MAX_EDIT_BYTES = 1024 * 1024; // ~1 MB
43	/** Max size (bytes) for a single upload from the Matrix console input bar. */
44	const MAX_UPLOAD_BYTES = 15 * 1024 * 1024; // 15 MB
45	
46	type ListResult = { ok: true; path: string; entries: FileEntry[] } | { ok: false; error: string };
47	type ReadResult =
48	  | { ok: true; path: string; content: string; truncated: false }
49	  | { ok: false; error: string };
50	type MutResult = { ok: true } | { ok: false; error: string };
51	
52	/**
53	 * Load the server if (and only if) the caller owns it (or is an admin). Returns
54	 * the exact fields lib/sftp needs to open a connection. Throws generic errors
55	 * that the wrappers translate to typed results.
56	 */
57	async function ownedServer(serverId: string) {
58	  const user = await requireUser();
59	  const server = await db.server.findUnique({
60	    where: { id: serverId },
61	    select: {
62	      id: true,
63	      userId: true,
64	      status: true,
65	      rootPassword: true,
66	      rootPasswordEnc: true,
67	      sshPort: true,
68	      dedicatedIp: { select: { address: true } },
69	      node: { select: { publicIp: true } },
70	    },
71	  });
72	  if (!server) throw new Error("Not found");
73	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
74	  return { user, server };
75	}
76	
77	/** Per-user throttle. Returns an error string when the caller should back off. */
78	function throttle(userId: string, op: string, max: number): string | null {
79	  const rl = checkRateLimit(`files:${op}:${userId}`, { max, windowMs: 60_000 });
80	  if (!rl.ok) return `Too many requests — slow down and retry in ${rl.retryAfterSec}s.`;
81	  return null;
82	}
83	
84	function toMode(mode: number | null): string | null {
85	  return mode == null ? null : (mode & 0o777).toString(8).padStart(3, "0");
86	}
87	
88	function entryOut(e: SftpEntry): FileEntry {
89	  return {
90	    name: e.name,
91	    isDirectory: e.isDirectory,
92	    size: e.size,
93	    modifiedMs: e.modifiedMs,
94	    mode: toMode(e.mode),
95	  };
96	}
97	
98	/** Map an internal error to a safe, user-facing message. */
99	function safeError(err: unknown): string {
100	  const msg = err instanceof Error ? err.message : String(err);
101	  if (msg === "Not found" || msg === "Forbidden") return "Server not found.";
102	  // Path/traversal/size messages from lib/sftp are already user-safe.
103	  if (
104	    /traversal|absolute|too long|too large|Invalid|No such|Not a (file|directory)|already exists|reachable|root password|is a directory/i.test(
105	      msg
106	    )
107	  ) {
108	    return msg;
109	  }
110	  // Anything else (connection/protocol errors) — keep it generic.
111	  return "Could not reach the server's filesystem. Please try again shortly.";
112	}
113	
114	// ---------------------------------------------------------------------------
115	
116	export async function listFiles(serverId: string, path: string): Promise<ListResult> {
117	  try {
118	    const { user, server } = await ownedServer(serverId);
119	    const limited = throttle(user.id, "list", 120);
120	    if (limited) return { ok: false, error: limited };
121	    const clean = normalizePath(path || "/");
122	    const entries = await listDir(server, clean);
123	    return { ok: true, path: clean, entries: entries.map(entryOut) };
124	  } catch (err) {
125	    return { ok: false, error: safeError(err) };
126	  }
127	}
128	
129	export async function readFile(serverId: string, path: string): Promise<ReadResult> {
130	  try {
131	    const { user, server } = await ownedServer(serverId);
132	    const limited = throttle(user.id, "read", 120);
133	    if (limited) return { ok: false, error: limited };
134	    const clean = normalizePath(path);
135	    const content = await readFileText(server, clean, MAX_EDIT_BYTES);
136	    return { ok: true, path: clean, content, truncated: false };
137	  } catch (err) {
138	    return { ok: false, error: safeError(err) };
139	  }
140	}
141	
142	export async function saveFile(
143	  serverId: string,
144	  path: string,
145	  content: string
146	): Promise<MutResult> {
147	  try {
148	    const { user, server } = await ownedServer(serverId);
149	    const limited = throttle(user.id, "save", 60);
150	    if (limited) return { ok: false, error: limited };
151	    if (typeof content !== "string") return { ok: false, error: "Invalid content." };
152	    if (Buffer.byteLength(content, "utf8") > MAX_EDIT_BYTES) {
153	      return { ok: false, error: "File exceeds the 1 MB in-browser edit limit." };
154	    }
155	    const clean = normalizePath(path);
156	    await writeFileText(server, clean, content);
157	    return { ok: true };
158	  } catch (err) {
159	    return { ok: false, error: safeError(err) };
160	  }
161	}
162	
163	export async function createFolder(
164	  serverId: string,
165	  path: string,
166	  name: string
167	): Promise<MutResult> {
168	  try {
169	    const { user, server } = await ownedServer(serverId);
170	    const limited = throttle(user.id, "mkdir", 60);
171	    if (limited) return { ok: false, error: limited };
172	    const dir = normalizePath(path);
173	    const clean = validateName(name.trim());
174	    await mkdirPath(server, joinPath(dir, clean));
175	    return { ok: true };
176	  } catch (err) {
177	    return { ok: false, error: safeError(err) };
178	  }
179	}
180	
181	export async function renameEntry(
182	  serverId: string,
183	  path: string,
184	  newName: string
185	): Promise<MutResult> {
186	  try {
187	    const { user, server } = await ownedServer(serverId);
188	    const limited = throttle(user.id, "rename", 60);
189	    if (limited) return { ok: false, error: limited };
190	    const from = normalizePath(path);
191	    if (from === "/") return { ok: false, error: "The root directory cannot be renamed." };
192	    const clean = validateName(newName.trim());
193	    const parent = from.slice(0, from.lastIndexOf("/")) || "/";
194	    await renamePath(server, from, joinPath(parent, clean));
195	    return { ok: true };
196	  } catch (err) {
197	    return { ok: false, error: safeError(err) };
198	  }
199	}
200	
201	export async function deleteEntry(serverId: string, path: string): Promise<MutResult> {
202	  try {
203	    const { user, server } = await ownedServer(serverId);
204	    const limited = throttle(user.id, "delete", 60);
205	    if (limited) return { ok: false, error: limited };
206	    const clean = normalizePath(path);
207	    if (clean === "/") return { ok: false, error: "The root directory cannot be deleted." };
208	    await removePath(server, clean);
209	    return { ok: true };
210	  } catch (err) {
211	    return { ok: false, error: safeError(err) };
212	  }
213	}
214	
215	export async function chmodEntry(
216	  serverId: string,
217	  path: string,
218	  mode: string
219	): Promise<MutResult> {
220	  try {
221	    const { user, server } = await ownedServer(serverId);
222	    const limited = throttle(user.id, "chmod", 60);
223	    if (limited) return { ok: false, error: limited };
224	    const clean = normalizePath(path);
225	    if (!/^[0-7]{3,4}$/.test(mode)) {
226	      return { ok: false, error: "Mode must be an octal value like 644 or 755." };
227	    }
228	    await chmodPath(server, clean, parseInt(mode, 8));
229	    return { ok: true };
230	  } catch (err) {
231	    return { ok: false, error: safeError(err) };
232	  }
233	}
234	
235	/**
236	 * Upload a single file from the browser to the customer's server over SFTP,
237	 * landing it under {@link UPLOAD_DIR} with a sanitized basename, and return the
238	 * absolute remote path so the caller can reference it (e.g. type it into the
239	 * `claude` CLI, which reads file/image paths).
240	 *
241	 * SECURITY. Like every action here it `requireUser()`s + ownership-checks the
242	 * target server INSIDE the function (via `ownedServer`, which enforces
243	 * `userId === caller` unless admin) before any credential is touched, so a
244	 * caller can never write onto another tenant's box. The destination is fixed to
245	 * UPLOAD_DIR + a `validateName`d basename — a path-traversal write is
246	 * structurally impossible. Size is capped both before and after base64 decode.
247	 *
248	 * `base64` accepts either a raw base64 string or a `data:...;base64,<payload>`
249	 * data URL (the shape a browser FileReader / paste produces).
250	 */
251	export async function uploadToServer(
252	  serverId: string,
253	  filename: string,
254	  base64: string
255	): Promise<{ ok: true; path: string; name: string } | { ok: false; error: string }> {
256	  try {
257	    const { user, server } = await ownedServer(serverId);
258	    const limited = throttle(user.id, "upload", 30);
259	    if (limited) return { ok: false, error: limited };
260	
261	    if (typeof base64 !== "string" || base64.length === 0) {
262	      return { ok: false, error: "No file data was provided." };
263	    }
264	    // Accept a data: URL payload OR a bare base64 string.
265	    const comma = base64.indexOf(",");
266	    const payload = base64.startsWith("data:") && comma !== -1 ? base64.slice(comma + 1) : base64;
267	    // Cheap size guard BEFORE decoding: base64 inflates bytes by ~4/3.
268	    if (payload.length > Math.ceil((MAX_UPLOAD_BYTES * 4) / 3) + 8) {
269	      return { ok: false, error: "File exceeds the 15 MB upload limit." };
270	    }
271	
272	    const buffer = Buffer.from(payload, "base64");
273	    if (buffer.length === 0) return { ok: false, error: "The file is empty or could not be decoded." };
274	    if (!Number.isFinite(buffer.length) || buffer.length > MAX_UPLOAD_BYTES) {
275	      return { ok: false, error: "File exceeds the 15 MB upload limit." };
276	    }
277	
278	    const name = sanitizeUploadName(filename);
279	    const remotePath = joinPath(UPLOAD_DIR, name);
280	
281	    // Ensure the uploads dir exists (best-effort: a pre-existing dir is fine;
282	    // the write below is the authoritative op and surfaces any real failure).
283	    try {
284	      await mkdirPath(server, UPLOAD_DIR);
285	    } catch {
286	      /* already exists / benign — the write will fail loudly if not */
287	    }
288	    await writeFileBuffer(server, remotePath, buffer);
289	    return { ok: true, path: remotePath, name };
290	  } catch (err) {
291	    return { ok: false, error: safeError(err) };
292	  }
293	}
294	
295	/** Lightweight stat used to disambiguate file vs. dir before an action. */
296	export async function statEntry(
297	  serverId: string,
298	  path: string
299	): Promise<{ ok: true; isDirectory: boolean; size: number } | { ok: false; error: string }> {
300	  try {
301	    const { user, server } = await ownedServer(serverId);
302	    const limited = throttle(user.id, "stat", 120);
303	    if (limited) return { ok: false, error: limited };
304	    const clean = normalizePath(path);
305	    const s = await statPath(server, clean);
306	    return { ok: true, isDirectory: s.isDirectory, size: s.size };
307	  } catch (err) {
308	    return { ok: false, error: safeError(err) };
309	  }
310	}
