27	const EDITABLE = /\.(txt|log|json|ya?ml|toml|ini|cfg|conf|properties|sh|bat|md|env|xml|js|ts|css|html|lock|gitignore)$/i;
28	const MAX_EDIT_BYTES = 1024 * 1024;
29	
30	function isEditable(e: FileEntry): boolean {
31	  return !e.isDirectory && (EDITABLE.test(e.name) || !e.name.includes(".")) && e.size <= MAX_EDIT_BYTES;
32	}
