34	function joinPath(dir: string, name: string): string {
35	  return dir === "/" ? `/${name}` : `${dir}/${name}`;
36	}
37	
38	function parentOf(p: string): string {
39	  if (p === "/" || !p.includes("/")) return "/";
40	  const up = p.slice(0, p.lastIndexOf("/"));
41	  return up === "" ? "/" : up;
42	}
