3	import { useCallback, useRef, useState } from "react";
4	import { Icon } from "@/components/nx/Icon";
5	import { beginUpload, endUpload } from "@/lib/upload-in-progress";
6	
7	/**
8	 * Uploads with a progress bar that reflects bytes actually sent.
9	 *
10	 * The file manager used `fetch` with a FormData body, which gives no upload
11	 * progress at all — the whole UI was one boolean and a button that read
12	 * "Uploading…". On a 200 MB world that is several minutes of a customer not
13	 * knowing whether anything is happening. `fetch` cannot report request-body
14	 * progress in any browser today, so this uses XMLHttpRequest, whose
15	 * `upload.onprogress` gives loaded/total for free.
16	 *
17	 * Files upload one at a time on purpose: the destination is a single SSH/SFTP
18	 * connection per request, and three concurrent 200 MB writes to one VM is a
19	 * worse experience than three sequential ones, not a better one.
20	 */
21	
22	export type UploadItem = {
23	  id: string;
24	  name: string;
25	  size: number;
26	  sent: number;
27	  /** bytes/second over the last sample window; null until there are two samples */
28	  rate: number | null;
29	  status: "queued" | "uploading" | "done" | "failed" | "cancelled";
30	  error?: string;
31	};
