33	function fmtSize(b: number): string {
34	  if (b < 1024) return `${b} B`;
35	  if (b < 1024 ** 2) return `${(b / 1024).toFixed(1)} KB`;
36	  if (b < 1024 ** 3) return `${(b / 1024 ** 2).toFixed(1)} MB`;
37	  return `${(b / 1024 ** 3).toFixed(2)} GB`;
38	}
39	
40	function fmtEta(item: UploadItem): string {
41	  if (item.status !== "uploading" || !item.rate || item.rate <= 0) return "";
42	  const left = Math.max(0, item.size - item.sent) / item.rate;
43	  if (left < 60) return `${Math.ceil(left)}s left`;
44	  return `${Math.ceil(left / 60)}m left`;
45	}
