47	export function useUploadQueue(serverId: string, path: string, onDone: () => void) {
48	  const [items, setItems] = useState<UploadItem[]>([]);
49	  const xhrRef = useRef<XMLHttpRequest | null>(null);
50	  const runningRef = useRef(false);
51	
52	  const patch = (id: string, p: Partial<UploadItem>) =>
53	    setItems((xs) => xs.map((x) => (x.id === id ? { ...x, ...p } : x)));
54	
55	  const sendOne = (item: UploadItem, file: File) =>
56	    new Promise<void>((resolve) => {
57	      const xhr = new XMLHttpRequest();
58	      xhrRef.current = xhr;
59	      let lastT = Date.now();
60	      let lastB = 0;
61	
62	      xhr.upload.onprogress = (e) => {
63	        if (!e.lengthComputable) return;
64	        const now = Date.now();
65	        const dt = (now - lastT) / 1000;
66	        // Sample the rate rather than computing it from the start, so a stall
67	        // shows as a stall instead of being averaged away.
68	        const rate = dt > 0.25 ? (e.loaded - lastB) / dt : null;
69	        if (rate !== null) { lastT = now; lastB = e.loaded; }
70	        patch(item.id, { sent: e.loaded, status: "uploading", ...(rate !== null ? { rate } : {}) });
71	      };
72	      xhr.onload = () => {
73	        if (xhr.status >= 200 && xhr.status < 300) {
74	          patch(item.id, { sent: item.size, status: "done", rate: null });
75	        } else {
76	          let msg = `Upload failed (${xhr.status}).`;
77	          try { msg = JSON.parse(xhr.responseText)?.error || msg; } catch { /* keep the status */ }
78	          patch(item.id, { status: "failed", error: msg });
79	        }
80	        resolve();
81	      };
82	      xhr.onerror = () => { patch(item.id, { status: "failed", error: "Connection lost during upload." }); resolve(); };
83	      xhr.onabort = () => { patch(item.id, { status: "cancelled" }); resolve(); };
84	
85	      const fd = new FormData();
86	      fd.set("file", file);
87	      xhr.open("POST", `/api/files/${serverId}?path=${encodeURIComponent(path)}`);
88	      xhr.send(fd);
89	    });
90	
91	  const enqueue = useCallback(
92	    async (list: FileList | File[]) => {
93	      const files = Array.from(list);
94	      if (!files.length || runningRef.current) return;
95	
96	      const batch: UploadItem[] = files.map((f, i) => ({
97	        id: `${Date.now()}-${i}-${f.name}`,
98	        name: f.name,
99	        size: f.size,
100	        sent: 0,
101	        rate: null,
102	        status: "queued",
103	      }));
104	      setItems((xs) => [...xs.filter((x) => x.status !== "done"), ...batch]);
105	
106	      runningRef.current = true;
107	      // Suppress AutoRefresh's periodic router.refresh() for the duration —
108	      // without it a long upload can have the page pulled out from under it.
109	      beginUpload();
110	      try {
111	        for (let i = 0; i < files.length; i++) await sendOne(batch[i], files[i]);
112	      } finally {
113	        endUpload();
114	        runningRef.current = false;
115	        xhrRef.current = null;
116	        onDone();
117	      }
118	    },
119	    // eslint-disable-next-line react-hooks/exhaustive-deps -- sendOne closes over stable refs
120	    [serverId, path, onDone],
121	  );
122	
123	  const cancel = () => xhrRef.current?.abort();
124	  const dismiss = (id: string) => setItems((xs) => xs.filter((x) => x.id !== id));
125	  const clearDone = () => setItems((xs) => xs.filter((x) => x.status === "uploading" || x.status === "queued"));
126	
127	  return { items, enqueue, cancel, dismiss, clearDone, busy: runningRef.current };
128	}
