export async function createHostingBackup(accountId: string): Promise<HostingResult> {
  const ctx = await ownedActiveAccount(accountId);
  if ("error" in ctx) return { error: ctx.error };
  // Rate-limit: one backup task in flight at a time.
  const inFlight = await db.hostingTask.findFirst({ where: { accountId, kind: "BACKUP", status: { in: ["PENDING", "RUNNING"] } } });
  if (inFlight) return { error: "A backup is already running." };
  await db.hostingTask.create({ data: { accountId, kind: "BACKUP" } });
  revalidatePath("/dashboard/hosting");
  return { ok: true };
}

export async function listHostingBackups(accountId: string): Promise<{ id: string; sizeBytes: number; createdAt: string }[]> {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true } });
  if (!a) return [];
  if (a.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  const rows = await db.hostingBackup.findMany({ where: { accountId }, orderBy: { createdAt: "desc" } });
  return rows.map((b) => ({ id: b.id, sizeBytes: b.sizeBytes, createdAt: b.createdAt.toISOString() }));
}

export async function restoreHostingBackup(accountId: string, backupId: string): Promise<HostingResult> {
  const ctx = await ownedActiveAccount(accountId);
  if ("error" in ctx) return { error: ctx.error };
  const b = await db.hostingBackup.findFirst({ where: { id: backupId, accountId } });
  if (!b) return { error: "Backup not found." };
  await db.hostingTask.create({ data: { accountId, kind: "RESTORE", payload: JSON.stringify({ backupId }) } });
  revalidatePath("/dashboard/hosting");
  return { ok: true };
}

// ---------- File manager ----------------------------------------------------

async function ownedAccountWithNode(id: string) {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({ where: { id }, include: { node: true } });
  if (!a) return { error: "Not found." as const };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." as const };
  if (a.status !== "ACTIVE") return { error: "The account is still being set up." as const };
  return { user, a };
}

export type FsEntryView = { name: string; isDir: boolean; size: number; modified: number };

export async function hostingListFiles(accountId: string, relPath: string): Promise<{ error?: string; entries?: FsEntryView[]; path?: string }> {
  const ctx = await ownedAccountWithNode(accountId);
  if ("error" in ctx) return { error: ctx.error };
  const path = String(relPath ?? "").replace(/^\/+/, "");
  if (SANDBOX) return { entries: [{ name: "public_html", isDir: true, size: 0, modified: Date.now() }], path };
  const t = fsTargetFor(ctx.a);
  if (!t) return { error: "The file manager isn’t ready yet." };
  try {
    const entries = await fsList(t, path || "public_html");
    return { entries, path: path || "public_html" };
  } catch {
    return { error: "Couldn’t read that folder." };
  }
}

export async function hostingMkdir(accountId: string, relPath: string, name: string): Promise<HostingResult> {
  const ctx = await ownedAccountWithNode(accountId);
  if ("error" in ctx) return { error: ctx.error };
  const clean = String(name ?? "").trim().replace(/[^A-Za-z0-9._-]/g, "").slice(0, 60);
  if (!clean) return { error: "Enter a folder name." };
  if (SANDBOX) return { ok: true };
  const t = fsTargetFor(ctx.a);
  if (!t) return { error: "The file manager isn’t ready yet." };
  try { await fsMkdir(t, `${relPath}/${clean}`); return { ok: true }; }
  catch { return { error: "Couldn’t create the folder." }; }
}

export async function hostingDeleteFile(accountId: string, relPath: string, isDir: boolean): Promise<HostingResult> {
  const ctx = await ownedAccountWithNode(accountId);
  if ("error" in ctx) return { error: ctx.error };
  if (SANDBOX) return { ok: true };
  const t = fsTargetFor(ctx.a);
  if (!t) return { error: "The file manager isn’t ready yet." };
  try { await fsDelete(t, relPath, isDir); return { ok: true }; }
  catch { return { error: "Couldn’t delete it." }; }
}

// ---------- Subdomains + addon domains + cron (cPanel-class site mgmt) -------
// Every value that reaches the node shell is validated here (isValidUnixUsername
// / isValidHostingDomain / isValidSubdomainLabel / cron validators) AND re-checked
// in the worker. Caps are enforced inside a Serializable transaction so concurrent
// creates cannot both read a stale count and blow past the plan (same discipline
// as createHostingDatabase). The task is queued in the SAME tx as the row create.

const SITE_STATES = ["PENDING", "ACTIVE"] as const;
