  // is the fast, definitive pre-check now. We also still scan the three resource
  // tables so any legacy row created before the claims table existed is honoured.
  const host = normalizeClaimHostname(name);
  const [claim, prim, sub, addon] = await Promise.all([
    db.hostingHostnameClaim.count({ where: { hostname: host } }),
    db.hostingAccount.count({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } }),
    db.hostingSubdomain.count({ where: { fqdn: name, status: { in: [...SITE_STATES] } } }),
    db.hostingAddonDomain.count({ where: { domain: name, status: { in: [...SITE_STATES] } } }),
  ]);
  return claim + prim + sub + addon > 0;
}

