"use server";

/**
 * Shared-hosting file-manager server actions.
 *
 * lib/actions-hosting.ts already had three of these (hostingListFiles,
 * hostingMkdir, hostingDeleteFile) — enough for a listing with a New folder and
 * a Delete button, not enough to drive the real file manager, which also reads,
 * saves and renames. This module is the COMPLETE set that lib/files-adapters.ts
 * `hostingFileApi` binds to, and it keeps the same ownership discipline as the
 * originals: owner-or-admin, ACTIVE account, and the chrooted-SFTP target built
 * by `fsTargetFor` (which connects AS the jailed account user — see the header of
 * lib/hosting-fs.ts for why that, and not root, is what makes this safe).
 *
 * Paths here are chroot-RELATIVE ("public_html/wp-config.php"), never absolute:
 * the adapter has already mapped the browser's virtual "/" onto the account's
 * base directory, and lib/hosting-fs's `safeRel` rejects traversal on every call
 * as defence in depth.
 */

import { db } from "./db";
import { requireUser } from "./auth";
import { SANDBOX } from "./sandbox";
import type { FileEntry, FileMut } from "./files-types";
import {
  fsTargetFor,
  fsList,
  fsMkdir,
  fsDelete,
  fsRename,
  fsReadBuffer,
  fsWriteBuffer,
  fsStatSize,
  type FsEntry,
} from "./hosting-fs";

/** Max size (bytes) for a text file opened/saved in the inline editor. Matches
 *  the VPS file manager's limit so the same editor behaves the same either side. */
const MAX_EDIT_BYTES = 1024 * 1024; // 1 MB

const NOT_READY = "The file manager isn’t ready yet.";
/** Shown wherever SANDBOX means there is no filesystem behind this account at
 *  all. Deliberately says what it is rather than inventing a listing. */
const NO_NODE =
  "No hosting node is attached in this environment, so there are no files to read.";

/**
 * Owner (or admin) + ACTIVE account, including the node — the same check the
 * three original file actions in lib/actions-hosting.ts do, replicated here
 * because that one is a local helper in a file this module must not import from
 * (a "use server" file may only export async functions).
 */
async function ownedAccountWithNode(id: string) {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({ where: { id }, include: { node: true } });
  if (!a) return { error: "Not found." as const };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." as const };
  if (a.status !== "ACTIVE") return { error: "The account is still being set up." as const };
  return { user, a };
}

/** Octal permission string like "755" from the raw st_mode SFTP reported, or
 *  null when the server did not send one. Never a guessed default. */
function toMode(mode: number | null): string | null {
  return mode == null ? null : (mode & 0o777).toString(8).padStart(3, "0");
}

function entryOut(e: FsEntry): FileEntry {
  return {
    name: e.name,
    isDirectory: e.isDir,
    size: e.size,
    modifiedMs: e.modified,
    mode: toMode(e.mode),
  };
}

/** Trim a relative path to its parent, "" when it is already at the base. */
function parentRel(rel: string): string {
  const clean = rel.replace(/\/+$/, "");
  const cut = clean.lastIndexOf("/");
  return cut === -1 ? "" : clean.slice(0, cut);
}

/** Same sanitiser hostingMkdir uses for a new folder name. */
function safeName(name: string): string {
  return String(name ?? "").trim().replace(/[^A-Za-z0-9._-]/g, "").slice(0, 120);
}

// ---------------------------------------------------------------------------

export async function hostingFsList(
  accountId: string,
  relPath: string
): Promise<{ ok: true; entries: FileEntry[] } | { ok: false; error: string }> {
  const ctx = await ownedAccountWithNode(accountId);
  if ("error" in ctx) return { ok: false, error: ctx.error };
  // No node, no filesystem: an EMPTY listing is the truthful answer, and the
  // browser renders its own "this folder is empty" state over it. Inventing a
  // plausible-looking tree here would be inventing customer data.
  if (SANDBOX) return { ok: true, entries: [] };
  const t = fsTargetFor(ctx.a);
  if (!t) return { ok: false, error: NOT_READY };
  try {
    const entries = await fsList(t, relPath);
    return { ok: true, entries: entries.map(entryOut) };
  } catch {
    return { ok: false, error: "Couldn’t read that folder." };
  }
}

export async function hostingFsRead(
  accountId: string,
  relPath: string
): Promise<{ ok: true; content: string } | { ok: false; error: string }> {
  const ctx = await ownedAccountWithNode(accountId);
  if ("error" in ctx) return { ok: false, error: ctx.error };
  if (SANDBOX) return { ok: false, error: NO_NODE };
  const t = fsTargetFor(ctx.a);
  if (!t) return { ok: false, error: NOT_READY };
  try {
    // Stat first: fsReadBuffer concatenates the whole file into memory, so an
    // oversized file has to be refused BEFORE it is read, not after.
    const size = await fsStatSize(t, relPath);
    if (size > MAX_EDIT_BYTES) {
      return { ok: false, error: "File exceeds the 1 MB in-browser edit limit." };
    }
    const buf = await fsReadBuffer(t, relPath);
    return { ok: true, content: buf.toString("utf8") };
  } catch {
    return { ok: false, error: "Couldn’t open that file." };
  }
}

export async function hostingFsSave(
  accountId: string,
  relPath: string,
  content: string
): Promise<FileMut> {
  const ctx = await ownedAccountWithNode(accountId);
  if ("error" in ctx) return { ok: false, error: ctx.error };
  if (typeof content !== "string") return { ok: false, error: "Invalid content." };
  if (Buffer.byteLength(content, "utf8") > MAX_EDIT_BYTES) {
    return { ok: false, error: "File exceeds the 1 MB in-browser edit limit." };
  }
  if (SANDBOX) return { ok: true };
  const t = fsTargetFor(ctx.a);
  if (!t) return { ok: false, error: NOT_READY };
  try {
    await fsWriteBuffer(t, relPath, Buffer.from(content, "utf8"));
    return { ok: true };
  } catch {
    return { ok: false, error: "Couldn’t save that file." };
  }
}

export async function hostingFsMkdir(
  accountId: string,
  dirRelPath: string,
  name: string
): Promise<FileMut> {
  const ctx = await ownedAccountWithNode(accountId);
  if ("error" in ctx) return { ok: false, error: ctx.error };
  const clean = safeName(name);
  if (!clean) return { ok: false, error: "Enter a folder name." };
  if (SANDBOX) return { ok: true };
  const t = fsTargetFor(ctx.a);
  if (!t) return { ok: false, error: NOT_READY };
  const dir = String(dirRelPath ?? "").replace(/\/+$/, "");
  try {
    await fsMkdir(t, dir ? `${dir}/${clean}` : clean);
    return { ok: true };
  } catch {
    return { ok: false, error: "Couldn’t create the folder." };
  }
}

export async function hostingFsRename(
  accountId: string,
  relPath: string,
  newName: string
): Promise<FileMut> {
  const ctx = await ownedAccountWithNode(accountId);
  if ("error" in ctx) return { ok: false, error: ctx.error };
  const clean = safeName(newName);
  if (!clean) return { ok: false, error: "Enter a name." };
  const from = String(relPath ?? "").replace(/\/+$/, "");
  if (!from || from === ".") return { ok: false, error: "The root directory cannot be renamed." };
  if (SANDBOX) return { ok: true };
  const t = fsTargetFor(ctx.a);
  if (!t) return { ok: false, error: NOT_READY };
  // Rename stays in the SAME parent directory — this backs a Rename control,
  // not a Move one (the VPS `renameEntry` behaves identically).
  const parent = parentRel(from);
  const to = parent ? `${parent}/${clean}` : clean;
  try {
    await fsRename(t, from, to);
    return { ok: true };
  } catch {
    return { ok: false, error: "Couldn’t rename it." };
  }
}

export async function hostingFsDelete(
  accountId: string,
  relPath: string,
  isDirectory: boolean
): Promise<FileMut> {
  const ctx = await ownedAccountWithNode(accountId);
  if ("error" in ctx) return { ok: false, error: ctx.error };
  const clean = String(relPath ?? "").replace(/\/+$/, "");
  if (!clean || clean === ".") return { ok: false, error: "The root directory cannot be deleted." };
  if (SANDBOX) return { ok: true };
  const t = fsTargetFor(ctx.a);
  if (!t) return { ok: false, error: NOT_READY };
  try {
    await fsDelete(t, clean, isDirectory);
    return { ok: true };
  } catch {
    return { ok: false, error: "Couldn’t delete it." };
  }
}

// Client-side FileApi factories — the adapters that let ONE file manager drive
// two different backends.
//
// A VPS is reached over SSH/SFTP as root and thinks in absolute paths; a
// shared-hosting account is reached over chrooted SFTP as the jailed account
// user and thinks in paths relative to its own jail. FileBrowser knows about
// neither: it works in its own "/"-rooted virtual paths and calls a FileApi,
// and the translation lives here, one small function per source.
//
// This is a plain module, NOT "use server": it is imported from client
// components, and the server actions it closes over become client references
// when bundled. Keeping it separate from lib/files-types.ts matters for the same
// reason that file explains — a "use server" file may only export async
// functions, so neither the types nor these factories can live in one.

import {
  listFiles,
  readFile,
  saveFile,
  createFolder,
  renameEntry,
  deleteEntry,
  chmodEntry,
} from "./actions-files";
import {
  hostingFsList,
  hostingFsRead,
  hostingFsSave,
  hostingFsMkdir,
  hostingFsRename,
  hostingFsDelete,
} from "./actions-hosting-fs";
import type { FileApi } from "./files-types";

/**
 * A customer's own VPS, over the actions in lib/actions-files.ts. Paths are
 * already absolute "/"-rooted paths on the box, so no translation is needed —
 * the browser's virtual root IS the server's root.
 */
